"use client";
import { useEffect,useMemo,useState } from "react";
import { useRouter } from "next/navigation";
import { LayoutDashboard, Package, Boxes, ShoppingCart, Users, CreditCard, Megaphone, ChartNoAxesCombined, Settings, Search, Bell, ChevronDown, Menu, X, ArrowUpRight, ArrowDownRight, MoreHorizontal, Plus, Download, CircleAlert, CheckCircle2, Clock3, Truck, CircleDollarSign, CalendarDays, Filter, Eye, Pencil, Trash2, LogOut, ShieldCheck, Activity, TrendingUp, Wallet, Tags, Image, SlidersHorizontal } from "lucide-react";
type Order={id:string;customer:string;date:string;items:number;productSummary:string[];total:number;status:string;payment:string;payment_status?:string;dbId?:string};

const nav = [
  { title: "OVERVIEW", items: [["Dashboard Overview", "overview", LayoutDashboard]] },
  { title: "CATALOGUE", items: [["All Products", "products", Package], ["Add Product", "add-product", Plus], ["Categories", "categories", Tags], ["Product Variants", "variants", SlidersHorizontal], ["Product Images", "images", Image]] },
  { title: "INVENTORY", items: [["Available Stock", "stock", Boxes], ["Stock Adjustment", "adjustment", Activity], ["Low Stock", "low-stock", CircleAlert], ["Stock History", "stock-history", Clock3]] },
  { title: "SALES & CUSTOMERS", items: [["All Orders", "orders", ShoppingCart], ["Pending Orders", "pending", Clock3], ["Confirmed Orders", "confirmed", CheckCircle2], ["Processing", "processing", Activity], ["Shipped", "shipped", Truck], ["Delivered", "delivered", CheckCircle2], ["Cancelled / Returned", "cancelled", X], ["Customer List", "customers", Users], ["Customer Details", "customer-details", Users], ["Order History", "order-history", CalendarDays]] },
  { title: "FINANCE", items: [["Payment Records", "payments", CreditCard], ["Payment Verification", "verification", ShieldCheck], ["Refunds", "refunds", Wallet], ["Transaction History", "transactions", Activity]] },
  { title: "GROWTH", items: [["Coupons", "coupons", Tags], ["Discounts", "discounts", CircleDollarSign], ["Banners", "banners", Image], ["Promotions", "promotions", Megaphone]] },
  { title: "INSIGHTS", items: [["Sales Reports", "reports", ChartNoAxesCombined], ["Product Performance", "performance", TrendingUp], ["Profit & Expenses", "profit", Wallet], ["Export Reports", "export", Download]] },
  { title: "CONFIGURATION", items: [["Admin Users & Roles", "roles", ShieldCheck], ["Shipping Settings", "shipping", Truck], ["Payment Settings", "payment-settings", CreditCard], ["Website Settings", "website-settings", Settings]] }
] as any[];
const money=(n:number)=>"৳"+n.toLocaleString("en-BD");
const statusClass=(s:string)=>s.toLowerCase().replaceAll(" ","-");
export default function AdminDashboard(){const router=useRouter();const [active,setActive]=useState("overview");const [sidebar,setSidebar]=useState(false);const [expandedGroups,setExpandedGroups]=useState<string[]>(["CATALOGUE"]);const [search,setSearch]=useState("");const [orders,setOrders]=useState<Order[]>([]);const [customerRows,setCustomerRows]=useState<any[]>([]);const [notice,setNotice]=useState("");const [period,setPeriod]=useState("7 days");const [overview,setOverview]=useState<any>(null);const [notificationsOpen,setNotificationsOpen]=useState(false);const [readNotifications,setReadNotifications]=useState<string[]>([]);const [profileOpen,setProfileOpen]=useState(false);const [adminProfile,setAdminProfile]=useState<any>({full_name:"Store Admin",bio:"",hobbies:"",avatar_url:"",cover_url:"",phone:"",email:""});const [profileSaving,setProfileSaving]=useState(false);const [profileEdit,setProfileEdit]=useState(false);const [profileAvatarFile,setProfileAvatarFile]=useState<File|null>(null);const [profileCoverFile,setProfileCoverFile]=useState<File|null>(null);const [filter,setFilter]=useState("All");const [products,setProducts]=useState<any[]>([]);const [categories,setCategories]=useState<any[]>([]);const [modal,setModal]=useState(false);const [editingProduct,setEditingProduct]=useState<any>(null);const [categoryModal,setCategoryModal]=useState(false);const [editingCategory,setEditingCategory]=useState<any>(null);const [categoryForm,setCategoryForm]=useState({name:"",description:""});const [productForm,setProductForm]=useState({name:"",brand:"",category_id:"",price:"",stock:"",sku:"",description:"",image_url:"",sizes:"",color:"",compare_at_price:"",status:"active"});const [productImages,setProductImages]=useState<File[]>([]);const [imagePreviews,setImagePreviews]=useState<string[]>([]);const [saving,setSaving]=useState(false);const [opsRecords,setOpsRecords]=useState<any[]>([]);const [opsLoading,setOpsLoading]=useState(false);const [opsSaving,setOpsSaving]=useState(false);const [opsEditing,setOpsEditing]=useState<any>(null);const [opsForm,setOpsForm]=useState<any>({});
const current=nav.flatMap(g=>g.items).find((i:any)=>i[1]===active)?.[0]||"Dashboard Overview";
const metrics=[{label:"Total sales",value:money(Number(overview?.metrics?.totalSales||0)),delta:`${Number(overview?.metrics?.salesChange||0)>=0?"+":""}${Number(overview?.metrics?.salesChange||0)}%`,up:Number(overview?.metrics?.salesChange||0)>=0,icon:CircleDollarSign,desc:"vs previous period"},{label:"Total orders",value:Number(overview?.metrics?.totalOrders||0).toLocaleString("en-BD"),delta:`${Number(overview?.metrics?.ordersChange||0)>=0?"+":""}${Number(overview?.metrics?.ordersChange||0)}%`,up:Number(overview?.metrics?.ordersChange||0)>=0,icon:ShoppingCart,desc:"all-time orders"},{label:"Total customers",value:Number(overview?.metrics?.totalCustomers||0).toLocaleString("en-BD"),delta:"Live",up:true,icon:Users,desc:"registered customer profiles"},{label:"Net revenue",value:money(Number(overview?.metrics?.netRevenue||0)),delta:"Verified",up:true,icon:Wallet,desc:"verified payments only"}];
const visibleOrders=useMemo(()=>orders.filter(o=>(active==="orders"||active==="overview"||active==="order-history"||active==="pending"||active==="confirmed"||active==="processing"||active==="shipped"||active==="delivered"||active==="cancelled"||active==="verification"||active==="payments"||active==="transactions"||active==="refunds")&&(active==="pending"?o.status==="Pending":active==="confirmed"?o.status==="Confirmed":active==="processing"?o.status==="Processing":active==="shipped"?o.status==="Shipped":active==="delivered"?o.status==="Delivered":active==="cancelled"?o.status==="Cancelled":true)&&[o.id,o.customer,o.payment,o.status].some(v=>v.toLowerCase().includes(search.toLowerCase()))),[orders,active,search]);
// Live finance, growth and shipping module records.
const opsTable:Record<string,string>={refunds:"refund_requests",transactions:"payment_transactions",coupons:"coupons",discounts:"coupons",shipping:"shipping_zones",promotions:"promotions"};
const opsTitle:Record<string,string>={refunds:"Refund requests",transactions:"Transaction history",coupons:"Coupons",discounts:"Coupons & discounts",shipping:"Shipping zones",promotions:"Promotions"};
async function loadOpsRecords(section=active){const table=opsTable[section];if(!table)return;setOpsLoading(true);try{const r=await fetch("/api/admin/finance?table="+table,{cache:"no-store"});const d=await r.json();if(!r.ok)throw new Error(d.error||"Could not load records");setOpsRecords(d.records||[]);}catch(e){setNotice(e instanceof Error?e.message:"Could not load records.");}finally{setOpsLoading(false);}}
function beginOpsEdit(row:any=null){setOpsEditing(row);if(!row){setOpsForm(sectionDefaults(active));return;}setOpsForm({...row,cities:Array.isArray(row.cities)?row.cities.join(", "):"",starts_at:row.starts_at?String(row.starts_at).slice(0,16):"",ends_at:row.ends_at?String(row.ends_at).slice(0,16):"",starts_at_coupon:row.starts_at?String(row.starts_at).slice(0,16):"",expires_at:row.expires_at?String(row.expires_at).slice(0,16):""});}
function sectionDefaults(section:string){if(section==="refunds")return {order_id:"",amount:"",reason:"",status:"requested",provider_reference:"",admin_note:""};if(section==="transactions")return {order_id:"",transaction_type:"payment",provider:"manual",provider_reference:"",amount:"",status:"pending",notes:""};if(section==="coupons"||section==="discounts")return {code:"",description:"",discount_type:"percentage",discount_value:"",minimum_order:"0",usage_limit:"",starts_at:"",expires_at:"",is_active:true};if(section==="shipping")return {name:"",cities:"",delivery_fee:"0",free_shipping_threshold:"",estimated_days:"2-5 business days",is_active:true};return {name:"",description:"",promotion_type:"discount",config:{},starts_at:"",ends_at:"",is_active:true};}
function opsPayload(section:string,form:any){const v={...form};delete v.id;delete v.created_at;delete v.updated_at;delete v.requested_at;delete v.processed_at;delete v.created_by;delete v.requested_by;delete v.processed_by;delete v.payments;delete v.orders;if("cities" in v)v.cities=String(v.cities||"").split(",").map((x:string)=>x.trim()).filter(Boolean);for(const key of ["starts_at","ends_at","expires_at"])if(key in v)v[key]?new Date(v[key]).toISOString():v[key]=null;if("amount" in v&&v.amount!=="")v.amount=Number(v.amount);for(const key of ["delivery_fee","free_shipping_threshold","minimum_order","discount_value","usage_limit"])if(key in v)v[key]=v[key]===""?null:Number(v[key]);if(section==="refunds"||section==="transactions"){const order=orders.find(o=>o.dbId===v.order_id);if(!order)v.order_id=v.order_id||null;}return v;}
async function saveOpsRecord(e:React.FormEvent){e.preventDefault();setOpsSaving(true);try{const table=opsTable[active];const values=opsPayload(active,opsForm);const r=await fetch("/api/admin/finance",{method:opsEditing?"PATCH":"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(opsEditing?{table,id:opsEditing.id,values}:{table,values})});const d=await r.json();if(!r.ok)throw new Error(d.error||"Could not save record");setOpsEditing(null);setOpsForm({});await loadOpsRecords();setNotice(opsEditing?"Record updated successfully.":"Record created successfully.");}catch(e){setNotice(e instanceof Error?e.message:"Could not save record.");}finally{setOpsSaving(false);}}
async function quickOpsStatus(row:any,status:string){try{const table=opsTable[active];const r=await fetch("/api/admin/finance",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({table,id:row.id,values:active==="refunds"?{status,admin_note:row.admin_note||""}:active==="transactions"?{status}:active==="shipping"?{is_active:status==="true"}:active==="promotions"?{is_active:status==="true"}:{is_active:status==="true"}})});const d=await r.json();if(!r.ok)throw new Error(d.error||"Could not update status");await loadOpsRecords();setNotice("Status updated.");}catch(e){setNotice(e instanceof Error?e.message:"Could not update status.");}}
useEffect(()=>{if(opsTable[active]){setOpsEditing(null);setOpsForm({});void loadOpsRecords(active);}},[active]);
// Admin data loaders and mutation handlers are separate statements (keep real line breaks here).
async function loadAdminProfile(){const r=await fetch("/api/admin/profile",{cache:"no-store"});const d=await r.json();if(r.ok&&d.profile)setAdminProfile(d.profile);}
async function saveAdminProfile(e:React.FormEvent){e.preventDefault();setProfileSaving(true);try{const updated={...adminProfile};for(const [file,field] of [[profileAvatarFile,"avatar_url"],[profileCoverFile,"cover_url"]] as const){if(file){const form=new FormData();form.append("file",file);const upload=await fetch("/api/admin/product-image",{method:"POST",body:form});const uploaded=await upload.json();if(!upload.ok)throw new Error(uploaded.error||"Profile image upload failed");updated[field]=uploaded.image_url;}}const r=await fetch("/api/admin/profile",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(updated)});const d=await r.json();if(!r.ok)throw new Error(d.error||"Profile save failed");setAdminProfile(d.profile);setProfileAvatarFile(null);setProfileCoverFile(null);setProfileEdit(false);setNotice("Admin profile saved.");}catch(err){setNotice(err instanceof Error?err.message:"Profile save failed.");}finally{setProfileSaving(false);}}
async function loadOverview(){const response=await fetch("/api/admin/overview?period="+encodeURIComponent(period),{cache:"no-store"});const data=await response.json();if(!response.ok)throw new Error(data.error||"Could not load dashboard analytics");setOverview(data);}
async function loadOrders(){const response=await fetch("/api/admin/orders",{cache:"no-store"});const data=await response.json();if(!response.ok)throw new Error(data.error||"Could not load orders");setOrders((data.orders||[]).map((o:any)=>({id:o.order_number||o.id,dbId:o.id,customer:o.customer_name||"Customer",date:new Date(o.created_at).toLocaleDateString("en-GB",{day:"2-digit",month:"short",year:"numeric"}),items:(o.order_items||[]).reduce((n:number,i:any)=>n+Number(i.quantity||0),0),productSummary:(o.order_items||[]).map((i:any)=>`${i.product_name||"Product"}${i.sku?` · ${i.sku}`:""} × ${Number(i.quantity||0)}`),total:Number(o.total)||0,status:String(o.status||"pending").replace(/(^|_)([a-z])/g,(_:string,a:string,b:string)=>a+b.toUpperCase()).replace(/_/g," "),payment:o.payment_method==="bkash_manual"?"bKash":o.payment_method==="nagad_manual"?"Nagad":"Cash on delivery",payment_status:o.payment_status})));}
async function changeStatus(id:string,status:string){const order=orders.find(o=>o.id===id);if(!order)return;const dbId=(order as any).dbId;const normalized=status.toLowerCase().replace(/ /g,"_");try{const response=await fetch("/api/admin/orders",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:dbId,status:normalized})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Could not update order");await loadOrders();setNotice("Order status saved to database.");}catch(e){setNotice(e instanceof Error?e.message:"Could not update order status.");}}
async function changePayment(id:string,payment_status:string){const order=orders.find(o=>o.id===id);if(!order?.dbId)return;try{const response=await fetch("/api/admin/orders",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:order.dbId,payment_status})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Could not update payment");await loadOrders();setNotice("Payment status saved. Verify bKash/Nagad in the official account before marking verified.");}catch(e){setNotice(e instanceof Error?e.message:"Could not update payment status.");}}
async function loadProducts(){const response=await fetch("/api/admin/products",{cache:"no-store"});const data=await response.json();if(!response.ok)throw new Error(data.error||"Could not load products");setProducts((data.products||[]).map((p:any)=>({...p,category:p.categories?.name||"Uncategorised",stock:p.stock_quantity??0,status:p.status==="active"?"Active":p.status==="archived"?"Archived":"Draft",image_url:p.product_images?.[0]?.storage_path||"",image_urls:(p.product_images||[]).sort((a:any,b:any)=>a.sort_order-b.sort_order).map((image:any)=>image.storage_path)})));}
async function loadCategories(){const response=await fetch("/api/admin/categories",{cache:"no-store"});const data=await response.json();if(!response.ok)throw new Error(data.error||"Could not load categories");setCategories(data.categories||[]);}
useEffect(()=>{if(active==="customers"){fetch("/api/admin/customers",{cache:"no-store"}).then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.error||"Could not load customers");setCustomerRows(d.customers||[])}).catch(e=>setNotice(e.message));}if(["products","add-product","categories","low-stock","stock","overview"].includes(active)){loadProducts().catch(e=>setNotice(e.message));loadCategories().catch(e=>setNotice(e.message));}if(["orders","overview","order-history","pending","confirmed","processing","shipped","delivered","cancelled","verification","payments","transactions","refunds"].includes(active)){loadOrders().catch(e=>setNotice(e.message));}if(active==="overview"){loadAdminProfile().catch(()=>{});loadOverview().catch(e=>setNotice(e.message));const timer=window.setInterval(()=>{loadOverview().catch(()=>{});loadOrders().catch(()=>{});},30000);return()=>window.clearInterval(timer);}},[active,period]);
function openAddProduct(){setEditingProduct(null);setProductForm({name:"",brand:"",category_id:categories[0]?.id||"",price:"",stock:"",sku:"",description:"",image_url:"",sizes:"",color:"",compare_at_price:"",status:"active"});setProductImages([]);setImagePreviews([]);setModal(true);setActive("add-product");}
function openEditProduct(p:any){setEditingProduct(p);setProductForm({name:p.name||"",brand:p.brand||"",category_id:p.category_id||"",price:String(p.price??""),stock:String(p.stock_quantity??0),sku:p.sku||"",description:p.description||"",image_url:p.image_url||"",sizes:Array.isArray(p.sizes)?p.sizes.join(", "):"",color:p.color||"",compare_at_price:p.compare_at_price==null?"":String(p.compare_at_price),status:p.status==="active"?"active":p.status==="archived"?"archived":"draft"});setProductImages([]);setImagePreviews(p.image_urls|| (p.image_url?[p.image_url]:[]));setModal(true);}
async function addProduct(e:React.FormEvent){e.preventDefault();if(!editingProduct&&!productImages.length){setNotice("Please choose at least one product image file.");return}setSaving(true);try{const uploadedImageUrls:string[]=[];for(const file of productImages){const uploadForm=new FormData();uploadForm.append("file",file);const uploadResponse=await fetch("/api/admin/product-image",{method:"POST",body:uploadForm});const uploadData=await uploadResponse.json();if(!uploadResponse.ok)throw new Error(uploadData.error||"Image upload failed");uploadedImageUrls.push(uploadData.image_url);}const imageUrls=[...imagePreviews,...uploadedImageUrls].slice(0,5);const slugBase=productForm.name.toLowerCase().trim().normalize("NFKD").replace(/[\\u0300-\\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,""),slug=slugBase||("product-"+Date.now().toString(36));const payload={name:productForm.name,brand:productForm.brand,category_id:productForm.category_id||null,price:Number(productForm.price),stock_quantity:Number(productForm.stock),sku:productForm.sku.trim()||("NX-"+slug.slice(0,40)+"-"+Date.now().toString().slice(-6)),slug,description:productForm.description,sizes:productForm.sizes.split(",").map((size)=>size.trim()).filter(Boolean).filter((size,index,all)=>all.findIndex((item)=>item.toLowerCase()===size.toLowerCase())===index).slice(0,30),color:productForm.color.trim(),compare_at_price:productForm.compare_at_price.trim()?Number(productForm.compare_at_price):null,status:productForm.status,image_urls:imageUrls};const response=await fetch("/api/admin/products",{method:editingProduct?"PATCH":"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(editingProduct?{...payload,id:editingProduct.id}:payload)});const data=await response.json();if(!response.ok)throw new Error(data.error||"Could not save product");setModal(false);setProductImages([]);setImagePreviews([]);setNotice(editingProduct?"Product updated in database.":"Product and gallery images saved to database.");await loadProducts();setActive("products");}catch(e){setNotice(e instanceof Error?e.message:"Could not save product.");}finally{setSaving(false)}}
async function deleteProduct(id:string){if(!window.confirm("Archive this product? It will disappear from the public storefront."))return;try{const response=await fetch("/api/admin/products?id="+encodeURIComponent(id),{method:"DELETE"});const data=await response.json();if(!response.ok)throw new Error(data.error||"Could not archive product");await loadProducts();setNotice("Product archived and removed from storefront.");}catch(e){setNotice(e instanceof Error?e.message:"Could not archive product.");}}
async function saveCategory(e:React.FormEvent){e.preventDefault();setSaving(true);try{const payload={name:categoryForm.name,description:categoryForm.description};const response=await fetch("/api/admin/categories",{method:editingCategory?"PATCH":"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(editingCategory?{...payload,id:editingCategory.id}:payload)});const data=await response.json();if(!response.ok)throw new Error(data.error||"Could not save category");setCategoryModal(false);setEditingCategory(null);setCategoryForm({name:"",description:""});await loadCategories();setNotice(editingCategory?"Category updated.":"Category added.");}catch(e){setNotice(e instanceof Error?e.message:"Could not save category.");}finally{setSaving(false)}}
async function archiveCategory(id:string){if(!window.confirm("Hide this category from the storefront?"))return;try{const response=await fetch("/api/admin/categories?id="+encodeURIComponent(id),{method:"DELETE"});const data=await response.json();if(!response.ok)throw new Error(data.error||"Could not archive category");await loadCategories();setNotice("Category hidden from storefront.");}catch(e){setNotice(e instanceof Error?e.message:"Could not archive category.");}}
function exportCsv(){const rows=[["Order ID","Customer","Date","Items","Total","Status","Payment"],...orders.map(o=>[o.id,o.customer,o.date,String(o.items),String(o.total),o.status,o.payment])];const blob=new Blob([rows.map(r=>r.map(v=>"\""+v.replaceAll("\"","")+"\"").join(",")).join("\n")],{type:"text/csv;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="nexora-admin-orders.csv";a.click();URL.revokeObjectURL(url);setNotice("Demo order report exported.");}
async function logout(){try{const {createSupabaseBrowserClient}=await import("@/lib/supabase/client");await createSupabaseBrowserClient().auth.signOut()}finally{router.push("/admin/login");router.refresh()}}
return <main className="admin-shell"><aside className={"admin-sidebar "+(sidebar?"sidebar-open":"")}><div className="admin-side-brand"><a href="/admin">NEXORA<span>ADMIN</span></a><button onClick={()=>setSidebar(false)} aria-label="Close menu"><X size={19}/></button></div><div className="admin-store-pill"><div className="store-mark">N</div><div><b>NEXORA Store</b><small>Commerce workspace</small></div><ChevronDown size={15}/></div><nav className="admin-nav" aria-label="Admin navigation">{nav.map(group=><div className="admin-nav-group" key={group.title}><button type="button" className="admin-nav-group-toggle" aria-expanded={expandedGroups.includes(group.title)} onClick={()=>setExpandedGroups(old=>old.includes(group.title)?[]:[group.title])}><small>{group.title}</small><ChevronDown size={14} className={expandedGroups.includes(group.title)?"group-chevron expanded":"group-chevron"}/></button>{expandedGroups.includes(group.title)&&<div className="admin-nav-group-items">{group.items.map((item:any)=>{const Icon=item[2];return <button key={item[1]} className={active===item[1]?"active":""} onClick={()=>{setActive(item[1]);setSidebar(false);setNotice("");if(!expandedGroups.includes(group.title))setExpandedGroups([group.title])}}><Icon size={16}/><span>{item[0]}</span>{item[1]==="pending"&&<i>3</i>}</button>})}</div>}</div>)}</nav><div className="admin-sidebar-bottom"><div className="admin-online"><span/>Storefront status <b>Preview</b></div><button onClick={logout}><LogOut size={16}/> Sign out</button></div></aside>{sidebar&&<button className="admin-sidebar-scrim" onClick={()=>setSidebar(false)} aria-label="Close navigation"/>}<section className="admin-main"><header className="admin-topbar"><button className="admin-menu-toggle" onClick={()=>setSidebar(true)} aria-label="Open navigation"><Menu size={21}/></button><div className="admin-breadcrumb">Workspace <span>/</span> <b>{current}</b></div><div className="admin-top-actions"><label className="admin-search"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search orders, products..."/></label><div className="admin-notification-wrap"><button className="admin-icon-button" aria-label="Notifications" aria-expanded={notificationsOpen} onClick={()=>setNotificationsOpen(v=>!v)}><Bell size={18}/>{(overview?.notifications||[]).some((n:any)=>!readNotifications.includes(n.id))&&<><i/><span className="admin-notification-count">{(overview?.notifications||[]).filter((n:any)=>!readNotifications.includes(n.id)).length}</span></>}</button>{notificationsOpen&&<div className="admin-notification-popover"><div className="admin-notification-heading"><b>Recent orders</b><button onClick={()=>setReadNotifications((overview?.notifications||[]).map((n:any)=>n.id))}>Mark all read</button></div>{(overview?.notifications||[]).length?(overview.notifications as any[]).map((n:any)=><button className={"admin-notification-item "+(readNotifications.includes(n.id)?"read":"")} key={n.id} onClick={()=>{setReadNotifications(old=>old.includes(n.id)?old:[...old,n.id]);setNotificationsOpen(false);setActive("orders");}}><span className="admin-notification-dot"/><span><b>{n.title}</b><small>{n.description}</small><small>{new Date(n.created_at).toLocaleString("en-GB",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"})}</small></span></button>):<p className="admin-notification-empty">No orders yet.</p>}</div>}</div><div className="admin-profile-wrap"><button className="admin-user" onClick={()=>{setProfileOpen(v=>!v);if(!profileOpen)loadAdminProfile().catch(()=>{});}} aria-expanded={profileOpen}><div className="admin-avatar">{adminProfile.avatar_url?<img src={adminProfile.avatar_url} alt="" style={{width:"100%",height:"100%",objectFit:"cover",borderRadius:"50%"}}/>:(adminProfile.full_name||"A").slice(0,1).toUpperCase()}</div><div><b>{adminProfile.full_name||"Store Admin"}</b><small>Super administrator</small></div><ChevronDown size={14}/></button>{profileOpen&&<div className="admin-profile-menu">{adminProfile.cover_url&&<img className="admin-profile-cover" src={adminProfile.cover_url} alt="Cover"/>}<div className="admin-profile-menu-head">{adminProfile.avatar_url?<img src={adminProfile.avatar_url} alt="Profile"/>:<div className="admin-avatar">{(adminProfile.full_name||"A").slice(0,1).toUpperCase()}</div>}<div><b>{adminProfile.full_name||"Store Admin"}</b><small>{adminProfile.email}</small></div></div>{profileEdit?<form className="admin-profile-form" onSubmit={saveAdminProfile}><label>Full name<input value={adminProfile.full_name||""} onChange={e=>setAdminProfile({...adminProfile,full_name:e.target.value})}/></label><label>Phone<input value={adminProfile.phone||""} onChange={e=>setAdminProfile({...adminProfile,phone:e.target.value})}/></label><label>Bio<textarea rows={2} value={adminProfile.bio||""} onChange={e=>setAdminProfile({...adminProfile,bio:e.target.value})}/></label><label>Hobbies<input value={adminProfile.hobbies||""} onChange={e=>setAdminProfile({...adminProfile,hobbies:e.target.value})}/></label><label>Profile photo<input type="file" accept="image/jpeg,image/png,image/webp,image/avif" onChange={e=>setProfileAvatarFile(e.target.files?.[0]||null)}/><small>JPG, PNG, WEBP or AVIF · max 5 MB</small></label><label>Cover photo<input type="file" accept="image/jpeg,image/png,image/webp,image/avif" onChange={e=>setProfileCoverFile(e.target.files?.[0]||null)}/><small>JPG, PNG, WEBP or AVIF · max 5 MB</small></label><button className="admin-primary-btn" disabled={profileSaving}>{profileSaving?"Saving…":"Save profile"}</button></form>:<><p className="admin-profile-bio">{adminProfile.bio||"Add a short bio from Edit profile."}</p>{adminProfile.hobbies&&<p className="admin-profile-hobbies">Hobbies: {adminProfile.hobbies}</p>}<button className="admin-profile-action" onClick={()=>{setProfileEdit(true);setProfileOpen(true)}}>Edit profile</button><button className="admin-profile-action" onClick={()=>{setProfileOpen(false);router.push("/admin/account-settings")}}>Account settings</button></>}<button className="admin-profile-action logout" onClick={logout}><LogOut size={14}/> Sign out</button></div>}</div></div></header><div className="admin-content"><div className="admin-page-heading"><div><span className="admin-eyebrow">NEXORA COMMERCE SUITE</span><h1>{active==="overview"?"Good afternoon, Admin.":current}</h1><p>{active==="overview"?"Here’s what’s happening with your store today.":"Manage your store operations from one place."}</p></div><div className="admin-heading-actions"><button className="admin-secondary-btn" onClick={exportCsv}><Download size={15}/> Export</button><button className="admin-primary-btn" onClick={openAddProduct}><Plus size={16}/> Add product</button></div></div>{notice&&<div className="admin-notice"><CheckCircle2 size={16}/>{notice}<button onClick={()=>setNotice("")}><X size={15}/></button></div>}
{active==="overview"&&<><div className="admin-metrics">{metrics.map(m=><article className="admin-metric" key={m.label}><div className="metric-top"><span>{m.label}</span><i><m.icon size={18}/></i></div><strong>{m.value}</strong><div className="metric-bottom"><span className="metric-up"><ArrowUpRight size={14}/>{m.delta}</span><span>{m.desc}</span></div></article>)}</div><div className="admin-dashboard-grid"><section className="admin-panel admin-sales-panel"><div className="admin-panel-heading"><div><h2>Sales overview</h2><p>Revenue performance over time</p></div><select value={period} onChange={e=>setPeriod(e.target.value)}><option>7 days</option><option>30 days</option><option>90 days</option></select></div><div className="sales-chart"><div className="chart-y"><span>{money(Math.max(1,...(overview?.chart||[]).map((p:any)=>p.sales||0)))}</span><span>{money(Math.max(1,...(overview?.chart||[]).map((p:any)=>p.sales||0))*0.66)}</span><span>{money(Math.max(1,...(overview?.chart||[]).map((p:any)=>p.sales||0))*0.33)}</span><span>৳0</span></div><div className="chart-bars">{(overview?.chart||[]).map((point:any,i:number,arr:any[])=>{const max=Math.max(1,...arr.map((x:any)=>Number(x.sales||0)));return <div className="chart-bar-column" key={point.date} title={`${point.date}
Sales: ${money(point.sales)}
Cost: ${money(point.cost||0)}
Profit: ${money(Math.max(0,point.profit||0))}
Loss: ${money(point.loss||0)}
Orders: ${point.orders}`}><div className="chart-bar" style={{height:Math.max(2,Number(point.sales||0)/max*100)+"%"}}/><small>{point.label}</small></div>})}</div></div><div className="sales-panel-footer"><span><i/> Revenue</span><b>{money(Number(overview?.metrics?.totalSales||0))}</b><span className="metric-up">{Number(overview?.metrics?.salesChange||0)}%</span></div></section><section className="admin-panel"><div className="admin-panel-heading"><div><h2>Inventory alerts</h2><p>Products that need attention</p></div><button className="admin-text-btn" onClick={()=>setActive("low-stock")}>View all</button></div>{products.filter(p=>p.stock<=7).slice(0,4).map(p=><div className="low-stock-row" key={p.id}><div className="low-stock-thumb"><Package size={17}/></div><div className="low-stock-info"><b>{p.name}</b><small>{p.brand} · {p.id}</small></div><span className={p.stock===0?"stock-critical":"stock-low"}>{p.stock===0?"Out of stock":p.stock+" left"}</span></div>)}</section></div><section className="admin-panel admin-table-panel"><div className="admin-panel-heading"><div><h2>Recent orders</h2><p>Latest activity from your store</p></div><button className="admin-text-btn" onClick={()=>setActive("orders")}>View all orders <ArrowUpRight size={14}/></button></div>{renderOrders(orders.slice(0,5),changeStatus,changePayment)}</section><div className="admin-bottom-grid"><section className="admin-panel"><div className="admin-panel-heading"><div><h2>Top products</h2><p>Best sellers this month</p></div><button className="admin-text-btn" onClick={()=>setActive("performance")}>Details</button></div>{(overview?.topProducts||[]).map((p:any,i:number)=><div className="top-product-row" key={p.name}><span className="top-product-rank">0{i+1}</span><div className="top-product-icon"><Package size={17}/></div><div className="top-product-name"><b>{p.name}</b><small>{p.units} sold</small></div><strong>{money(p.revenue)}</strong></div>)}{!(overview?.topProducts||[]).length&&<p className="admin-no-results">No sales data yet.</p>}</section><section className="admin-panel"><div className="admin-panel-heading"><div><h2>Payment methods</h2><p>Order payment distribution</p></div><button className="admin-icon-button"><MoreHorizontal size={17}/></button></div>{(overview?.paymentBreakdown||[]).map((p:any)=><div className="payment-progress" key={p.method}><div><span>{String(p.method).replaceAll("_"," ")}</span><b>{p.percent}%</b></div><i><span style={{width:Math.min(100,p.percent)+"%"}}/></i></div>)}{!(overview?.paymentBreakdown||[]).length&&<p className="admin-no-results">No payment data yet.</p>}</section></div></>}
{active==="products"&&<section className="admin-panel admin-table-panel"><div className="admin-panel-heading"><div><h2>Product catalogue</h2><p>{products.length} products · live database</p></div><button className="admin-primary-btn" onClick={openAddProduct}><Plus size={15}/> Add product</button></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Product</th><th>SKU</th><th>Price</th><th>Stock</th><th>Status</th><th>Actions</th></tr></thead><tbody>{products.filter(p=>[p.name,p.brand,p.id].some(v=>v.toLowerCase().includes(search.toLowerCase()))).map(p=><tr key={p.id}><td><div className="admin-product-cell"><div className="admin-product-placeholder">{p.image_url?<img src={p.image_url} alt={p.name} style={{width:"100%",height:"100%",objectFit:"cover",borderRadius:8}}/>:<Package size={18}/>}</div><div><b>{p.name}</b><small>{p.brand} · {p.category}</small></div></div></td><td>{p.id}</td><td>{money(p.price)}</td><td><span className={p.stock<=5?"stock-critical":"stock-normal"}>{p.stock}</span></td><td><span className={"admin-status "+statusClass(p.status)}>{p.status}</span></td><td><button className="admin-row-action" onClick={()=>openEditProduct(p)}><Pencil size={14}/></button><button className="admin-row-action" onClick={()=>deleteProduct(p.id)}><Trash2 size={14}/></button></td></tr>)}</tbody></table></div></section>}
{(active==="stock"||active==="low-stock"||active==="adjustment"||active==="stock-history")&&<section className="admin-panel admin-table-panel"><div className="admin-panel-heading"><div><h2>{current}</h2><p>{active==="low-stock"?"Products with 7 or fewer units remaining":active==="adjustment"?"Select a product to update its stock quantity":active==="stock-history"?"Current stock overview from the live product catalogue":"Live inventory quantities from Supabase"}</p></div><button className="admin-secondary-btn" onClick={()=>{fetch("/api/admin/products",{cache:"no-store"}).then(r=>r.json()).then(d=>setProducts(d.products||[])).catch(()=>setNotice("Could not refresh inventory."))}}><Activity size={15}/> Refresh inventory</button></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Product</th><th>SKU</th><th>Sizes</th><th>Current stock</th><th>Status</th><th>Action</th></tr></thead><tbody>{products.filter((p:any)=>active!=="low-stock"||Number(p.stock)<=7).map((p:any)=><tr key={p.id}><td><div className="admin-product-cell"><div className="admin-product-placeholder">{p.image_url?<img src={p.image_url} alt={p.name} style={{width:"100%",height:"100%",objectFit:"cover",borderRadius:8}}/>:<Package size={18}/>}</div><div><b>{p.name}</b><small>{p.brand||p.category||"—"}</small></div></div></td><td>{p.id}</td><td>{Array.isArray(p.sizes)&&p.sizes.length?p.sizes.join(", "):"Not set"}</td><td><span className={Number(p.stock)===0?"stock-critical":Number(p.stock)<=7?"stock-low":"stock-normal"}>{Number(p.stock)||0}</span></td><td><span className={"admin-status "+statusClass(p.status)}>{p.status}</span></td><td><button className="admin-row-action" title="Adjust product stock" onClick={()=>openEditProduct(p)}><Pencil size={14}/></button></td></tr>)}</tbody></table>{products.filter((p:any)=>active!=="low-stock"||Number(p.stock)<=7).length===0&&<p className="admin-no-results">No products match this inventory view.</p>}</div></section>}{active==="categories"&&<section className="admin-panel admin-table-panel"><div className="admin-panel-heading"><div><h2>Categories</h2><p>{categories.length} categories · live database</p></div><button className="admin-primary-btn" onClick={()=>{setEditingCategory(null);setCategoryForm({name:"",description:""});setCategoryModal(true)}}><Plus size={15}/> Add category</button></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Category</th><th>Slug</th><th>Status</th><th>Actions</th></tr></thead><tbody>{categories.map((cat:any)=><tr key={cat.id}><td><b>{cat.name}</b><small style={{display:"block",color:"#858a98"}}>{cat.description||""}</small></td><td>{cat.slug}</td><td><span className={"admin-status "+(cat.is_active?"active":"archived")}>{cat.is_active?"Active":"Hidden"}</span></td><td><button className="admin-row-action" onClick={()=>{setEditingCategory(cat);setCategoryForm({name:cat.name,description:cat.description||""});setCategoryModal(true)}}><Pencil size={14}/></button><button className="admin-row-action" onClick={()=>archiveCategory(cat.id)}><Trash2 size={14}/></button></td></tr>)}</tbody></table>{!categories.length&&<p className="admin-no-results">No categories yet. Add your first category.</p>}</div></section>}
{active==="add-product"&&<section className="admin-panel admin-empty-module"><Package size={28}/><h2>Add a new product</h2><p>Create catalogue entries with price, category, brand and stock.</p><button className="admin-primary-btn" onClick={()=>setModal(true)}><Plus size={15}/> Open product form</button></section>}
{["refunds","transactions","coupons","discounts","shipping","promotions"].includes(active)&&<section className="admin-panel admin-table-panel"><div className="admin-panel-heading"><div><h2>{opsTitle[active]}</h2><p>{opsRecords.length} saved records · live database</p></div><div className="admin-table-tools"><button className="admin-secondary-btn" onClick={()=>loadOpsRecords()}><Activity size={14}/> Refresh</button><button className="admin-primary-btn" onClick={()=>beginOpsEdit()}><Plus size={15}/> Add {active==="refunds"?"refund":active==="transactions"?"transaction":active==="shipping"?"shipping zone":active==="promotions"?"promotion":"coupon"}</button></div></div>
{opsEditing!==null&&<form className="admin-panel" onSubmit={saveOpsRecord}><div className="admin-panel-heading"><div><h3>{opsEditing?"Edit record":"Create record"}</h3><p>Changes are saved to the secured admin API.</p></div><button type="button" className="admin-secondary-btn" onClick={()=>{setOpsEditing(null);setOpsForm({});}}>Cancel</button></div><div className="admin-form-grid">
{(active==="refunds"?["order_id","amount","reason","status","provider_reference","admin_note"]:active==="transactions"?["order_id","transaction_type","provider","provider_reference","amount","status","notes"]:(active==="coupons"||active==="discounts")?["code","description","discount_type","discount_value","minimum_order","usage_limit","starts_at","expires_at","is_active"]:active==="shipping"?["name","cities","delivery_fee","free_shipping_threshold","estimated_days","is_active"]:["name","description","promotion_type","starts_at","ends_at","is_active"]).map((key:string)=>{const val=opsForm[key]??"";const label=key.replaceAll("_"," ");if(key==="order_id")return <label className="admin-form-field" key={key}>{label}<select required value={val} onChange={e=>setOpsForm({...opsForm,[key]:e.target.value})}><option value="">Select order</option>{orders.filter(o=>o.dbId).map(o=><option key={o.dbId} value={o.dbId}>{o.id} · {o.customer} · {money(o.total)}</option>)}</select></label>;if(["status","transaction_type","discount_type","promotion_type"].includes(key)){const opts=key==="status"?(active==="refunds"?["requested","approved","rejected","processing","completed","failed"]:active==="transactions"?["pending","completed","failed","reversed"]:["pending","verified","rejected"]):key==="transaction_type"?["payment","refund","adjustment"]:key==="discount_type"?["percentage","fixed"]:["discount","seasonal","bundle","free_shipping"];return <label className="admin-form-field" key={key}>{label}<select value={val||opts[0]} onChange={e=>setOpsForm({...opsForm,[key]:e.target.value})}>{opts.map(x=><option key={x} value={x}>{x}</option>)}</select></label>;}if(key==="is_active")return <label className="admin-form-field" key={key}>{label}<select value={String(val===undefined?true:val)} onChange={e=>setOpsForm({...opsForm,[key]:e.target.value==="true"})}><option value="true">Active</option><option value="false">Inactive</option></select></label>;const type=["amount","delivery_fee","free_shipping_threshold","minimum_order","discount_value","usage_limit"].includes(key)?"number":["starts_at","ends_at","expires_at"].includes(key)?"datetime-local":"text";return <label className="admin-form-field" key={key}>{label}{key==="reason"||key==="admin_note"||key==="notes"||key==="description"||key==="cities"?<textarea required={key==="reason"||key==="name"} value={val} onChange={e=>setOpsForm({...opsForm,[key]:e.target.value})}/>:<input required={["name","code","amount","reason","discount_value","delivery_fee","provider_reference"].includes(key)&&!opsEditing} type={type} min={type==="number"?"0":undefined} value={val} onChange={e=>setOpsForm({...opsForm,[key]:e.target.value})} placeholder={key==="cities"?"Bogura, Dhaka, Rajshahi":label}/>}</label>})}
</div>{active==="promotions"&&<p className="admin-form-hint">Promotion config is currently saved as an empty JSON object. Configure additional campaign rules in a later iteration.</p>}<div className="admin-form-actions"><button type="submit" className="admin-primary-btn" disabled={opsSaving}>{opsSaving?"Saving…":opsEditing?"Save changes":"Create record"}</button></div></form>}
{opsLoading?<p className="admin-no-results">Loading live records…</p>:<div className="admin-table-wrap"><table className="admin-table"><thead><tr>{(active==="refunds"?["Order","Amount","Reason","Status","Provider ref","Requested"]:active==="transactions"?["Type","Order","Provider","Reference","Amount","Status","Created"]:active==="shipping"?["Zone","Cities","Delivery fee","Free shipping from","ETA","Status"]:active==="promotions"?["Promotion","Type","Start","End","Status"]:["Code","Discount","Minimum order","Usage limit","Expiry","Status"]).map(h=><th key={h}>{h}</th>)}<th>Actions</th></tr></thead><tbody>{opsRecords.map((row:any)=><tr key={row.id}>{active==="refunds"?<><td>{orders.find(o=>o.dbId===row.order_id)?.id||row.order_id}</td><td>{money(Number(row.amount||0))}</td><td>{row.reason}</td><td><select className="order-status-select" value={row.status} onChange={e=>quickOpsStatus(row,e.target.value)}>{["requested","approved","rejected","processing","completed","failed"].map(s=><option key={s}>{s}</option>)}</select></td><td>{row.provider_reference||"—"}</td><td>{row.requested_at?new Date(row.requested_at).toLocaleString():"—"}</td></>:active==="transactions"?<><td>{row.transaction_type}</td><td>{orders.find(o=>o.dbId===row.order_id)?.id||row.order_id||"—"}</td><td>{row.provider||"—"}</td><td>{row.provider_reference||"—"}</td><td>{money(Number(row.amount||0))}</td><td><select className="order-status-select" value={row.status} onChange={e=>quickOpsStatus(row,e.target.value)}>{["pending","completed","failed","reversed"].map(s=><option key={s}>{s}</option>)}</select></td><td>{row.created_at?new Date(row.created_at).toLocaleString():"—"}</td></>:active==="shipping"?<><td>{row.name}</td><td>{(row.cities||[]).join(", ")||"All areas"}</td><td>{money(Number(row.delivery_fee||0))}</td><td>{row.free_shipping_threshold==null?"—":money(Number(row.free_shipping_threshold))}</td><td>{row.estimated_days}</td><td>{row.is_active?"Active":"Inactive"}</td></>:active==="promotions"?<><td>{row.name}</td><td>{row.promotion_type}</td><td>{row.starts_at?new Date(row.starts_at).toLocaleDateString():"—"}</td><td>{row.ends_at?new Date(row.ends_at).toLocaleDateString():"—"}</td><td>{row.is_active?"Active":"Inactive"}</td></>:<><td>{row.code}</td><td>{row.discount_value}{row.discount_type==="percentage"?"%":" BDT"} ({row.discount_type})</td><td>{money(Number(row.minimum_order||0))}</td><td>{row.usage_limit??"Unlimited"}</td><td>{row.expires_at?new Date(row.expires_at).toLocaleDateString():"No expiry"}</td><td>{row.is_active?"Active":"Inactive"}</td></>}<td><div className="admin-table-tools"><button className="admin-row-action" title="Edit record" onClick={()=>beginOpsEdit(row)}><Pencil size={14}/></button>{["shipping","promotions","coupons","discounts"].includes(active)&&<button className="admin-secondary-btn" onClick={()=>quickOpsStatus(row,String(!row.is_active))}>{row.is_active?"Disable":"Enable"}</button>}</div></td></tr>)}</tbody></table>{opsRecords.length===0&&<p className="admin-no-results">No records yet. Use Add to create the first record.</p>}</div>}</section>}
{["reports","performance","profit","export"].includes(active)&&<section className="admin-panel admin-table-panel"><div className="admin-panel-heading"><div><h2>{current}</h2><p>Computed from live order and product data currently loaded in this dashboard.</p></div><button className="admin-primary-btn" onClick={exportCsv}><Download size={15}/> Export orders CSV</button></div><div className="admin-metric-grid"><div className="admin-panel"><small>Order count</small><h2>{orders.length}</h2></div><div className="admin-panel"><small>Gross order value</small><h2>{money(orders.reduce((n,o)=>n+o.total,0))}</h2></div><div className="admin-panel"><small>Delivered order value</small><h2>{money(orders.filter(o=>o.status.toLowerCase()==="delivered").reduce((n,o)=>n+o.total,0))}</h2></div><div className="admin-panel"><small>Cancelled order value</small><h2>{money(orders.filter(o=>o.status.toLowerCase()==="cancelled").reduce((n,o)=>n+o.total,0))}</h2></div></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Order</th><th>Customer</th><th>Products</th><th>Order status</th><th>Payment status</th><th>Total</th></tr></thead><tbody>{orders.map(o=><tr key={o.id}><td>{o.id}</td><td>{o.customer}</td><td>{o.productSummary.join("; ")||"—"}</td><td>{o.status}</td><td>{o.payment_status||"unpaid"}</td><td><b>{money(o.total)}</b></td></tr>)}</tbody></table></div></section>}
{["coupons","discounts","banners","promotions","variants","images","customer-details","roles","shipping","payment-settings","website-settings","order-history"].includes(active)?<section className="admin-module-grid"><section className="admin-panel admin-module-intro"><div className="module-icon"><Settings size={20}/></div><span className="admin-eyebrow">WORKSPACE MODULE</span><h2>{current}</h2><p>This feature still needs its own database schema and secured API before create/edit actions can safely change the live store. It is not presented as live CRUD yet.</p><div className="module-stats"><div><small>Workspace</small><b>NEXORA Store</b></div><div><small>Data mode</small><b>Backend required</b></div></div></section><section className="admin-panel"><div className="admin-panel-heading"><div><h2>Available actions</h2><p>Actions currently connected to live data</p></div></div><div className="module-quick-actions"><button onClick={exportCsv}><Download size={17}/><span><b>Export order records</b><small>Download real order data as CSV</small></span><ArrowUpRight size={15}/></button><button onClick={()=>setActive("orders")}><ShoppingCart size={17}/><span><b>Manage orders</b><small>Review and update order status</small></span><ArrowUpRight size={15}/></button></div></section></section>:null}
{["orders","pending","confirmed","processing","shipped","delivered","cancelled"].includes(active)&&<section className="admin-panel admin-table-panel"><div className="admin-panel-heading"><div><h2>{current}</h2><p>{visibleOrders.length} orders in this view</p></div><div className="admin-table-tools"><button className="admin-secondary-btn" onClick={()=>setFilter(filter==="All"?"bKash":"All")}><Filter size={14}/>{filter==="All"?"Filter payments":"Clear filter"}</button><button className="admin-secondary-btn" onClick={exportCsv}><Download size={14}/> Export</button></div></div>{renderOrders(visibleOrders.filter(o=>filter==="All"||o.payment===filter),changeStatus,changePayment)}</section>}
{active==="order-history"&&<section className="admin-panel"><h2>Customer order history</h2><p>Choose All Orders to review order details in this demo.</p><button className="admin-primary-btn" onClick={()=>setActive("orders")}>Open all orders</button></section>}
{active==="customers"&&<section className="admin-panel admin-table-panel"><div className="admin-panel-heading"><div><h2>Customer accounts</h2><p>{customerRows.length} registered customers · live Supabase data</p></div><button className="admin-secondary-btn" onClick={()=>fetch("/api/admin/customers",{cache:"no-store"}).then(r=>r.json()).then(d=>setCustomerRows(d.customers||[])).catch(()=>setNotice("Could not refresh customers."))}><Activity size={15}/> Refresh</button></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Customer</th><th>Phone</th><th>Joined</th><th>Orders</th><th>Total spent</th><th>Last order</th></tr></thead><tbody>{customerRows.filter((x:any)=>[x.full_name,x.email,x.phone,x.id].some(v=>String(v||"").toLowerCase().includes(search.toLowerCase()))).map((customer:any)=><tr key={customer.id}><td><div className="admin-product-cell"><div className="admin-avatar">{(customer.full_name||"C").slice(0,1).toUpperCase()}</div><div><b>{customer.full_name||"Customer"}</b><small>{customer.email||"Email unavailable"}</small></div></div></td><td>{customer.phone||"—"}</td><td>{customer.created_at?new Date(customer.created_at).toLocaleDateString("en-GB"):"—"}</td><td>{customer.orderCount}</td><td><b>{money(customer.totalSpent)}</b></td><td>{customer.lastOrderAt?new Date(customer.lastOrderAt).toLocaleDateString("en-GB"):"No orders yet"}</td></tr>)}</tbody></table>{customerRows.length===0&&<p className="admin-no-results">No registered customer accounts found yet.</p>}</div></section>}{modal&&<div className="admin-modal-backdrop" onClick={()=>setModal(false)}><form className="admin-modal" onSubmit={addProduct} onClick={e=>e.stopPropagation()}><button type="button" className="admin-modal-close" onClick={()=>setModal(false)}><X size={18}/></button><span className="admin-eyebrow">CATALOGUE MANAGEMENT</span><h2>{editingProduct?"Edit product":"Add product"}</h2><label>Product name<input required maxLength={160} value={productForm.name} onChange={e=>setProductForm({...productForm,name:e.target.value})}/></label><label>Brand<input value={productForm.brand} maxLength={120} onChange={e=>setProductForm({...productForm,brand:e.target.value})}/></label><label>Category<select value={productForm.category_id} onChange={e=>setProductForm({...productForm,category_id:e.target.value})}><option value="">Uncategorised</option>{categories.filter((x:any)=>x.is_active).map((cat:any)=><option key={cat.id} value={cat.id}>{cat.name}</option>)}</select></label><div className="admin-form-two"><label>Price (BDT)<input type="number" min="0" step="0.01" required value={productForm.price} onChange={e=>setProductForm({...productForm,price:e.target.value})}/></label><label>Stock quantity<input type="number" min="0" step="1" required value={productForm.stock} onChange={e=>setProductForm({...productForm,stock:e.target.value})}/></label></div><label>SKU (optional; generated if blank)<input value={productForm.sku} maxLength={80} onChange={e=>setProductForm({...productForm,sku:e.target.value})}/></label><label>Available sizes (comma-separated)<input value={productForm.sizes} maxLength={500} onChange={e=>setProductForm({...productForm,sizes:e.target.value})} placeholder="e.g. 39, 40, 41, 42, 43, 44"/><small className="admin-form-hint">Add, remove, or reorder sizes for this product. Maximum 30 unique sizes.</small></label><div className="admin-form-two"><label>Color<input value={productForm.color} maxLength={80} onChange={e=>setProductForm({...productForm,color:e.target.value})} placeholder="e.g. White / Black"/></label><label>Compare-at price (BDT)<input type="number" min="0" step="0.01" value={productForm.compare_at_price} onChange={e=>setProductForm({...productForm,compare_at_price:e.target.value})} placeholder="Optional original price"/></label></div><label>Product images (main image + up to 4 gallery images){imagePreviews.length>0&&<div className="admin-gallery-preview">{imagePreviews.map((src,i)=><div key={src+"-"+i}><img src={src} alt={"Product image "+(i+1)}/><button type="button" onClick={()=>setImagePreviews(old=>old.filter((_,index)=>index!==i))}>Remove</button><small>{i===0?"Main image":"Gallery image "+(i+1)}</small></div>)}</div>}<input type="file" accept="image/jpeg,image/png,image/webp,image/avif" multiple required={!editingProduct&&!imagePreviews.length&&!productImages.length} onChange={e=>{const files=Array.from(e.target.files||[]);if(files.some(file=>file.size>5*1024*1024)){setNotice("Each image must be smaller than 5 MB.");e.currentTarget.value="";return}const room=5-imagePreviews.length;if(files.length>room){setNotice("A product can have up to 5 images total.");e.currentTarget.value="";return}setProductImages(files.slice(0,room));setImagePreviews(old=>old.filter((_,i)=>i<Math.max(0,5-files.length)));}}/><small>Select up to 5 image files: first is the main image, the remaining 4 appear as thumbnails. JPG, PNG, WEBP or AVIF, maximum 5 MB each. No image URLs.</small></label><label>Description<textarea rows={3} value={productForm.description} onChange={e=>setProductForm({...productForm,description:e.target.value})}/></label><label>Status<select value={productForm.status} onChange={e=>setProductForm({...productForm,status:e.target.value})}><option value="draft">Draft</option><option value="active">Active (publish)</option></select></label><button className="admin-primary-btn" type="submit" disabled={saving}>{saving?"Saving…":editingProduct?"Update product":"Save product"}</button></form></div>}{categoryModal&&<div className="admin-modal-backdrop" onClick={()=>setCategoryModal(false)}><form className="admin-modal" onSubmit={saveCategory} onClick={e=>e.stopPropagation()}><button type="button" className="admin-modal-close" onClick={()=>setCategoryModal(false)}><X size={18}/></button><span className="admin-eyebrow">CATALOGUE MANAGEMENT</span><h2>{editingCategory?"Edit category":"Add category"}</h2><label>Category name<input required maxLength={100} value={categoryForm.name} onChange={e=>setCategoryForm({...categoryForm,name:e.target.value})}/></label><label>Description<textarea rows={3} value={categoryForm.description} onChange={e=>setCategoryForm({...categoryForm,description:e.target.value})}/></label><button className="admin-primary-btn" type="submit" disabled={saving}>{saving?"Saving…":editingCategory?"Update category":"Save category"}</button></form></div>}</div></section></main>}
function renderOrders(rows:Order[],changeStatus:(id:string,status:string)=>void,changePayment:(id:string,status:string)=>void){return <div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Order ID</th><th>Customer</th><th>Date</th><th>Products ordered</th><th>Qty</th><th>Total</th><th>Payment</th><th>Payment status</th><th>Order status</th></tr></thead><tbody>{rows.map(o=><tr key={o.id}><td><b>{o.id}</b></td><td>{o.customer}</td><td>{o.date}</td><td><div className="order-product-list">{o.productSummary.length?o.productSummary.map((name,index)=><div key={index}>{name}</div>):<span className="order-product-legacy">Product details unavailable for this order</span>}</div></td><td>{o.items}</td><td><b>{money(o.total)}</b></td><td>{o.payment}</td><td><select aria-label={"Payment status for "+o.id} className={"order-status-select "+statusClass(o.payment_status||"unpaid")} value={o.payment_status||"unpaid"} onChange={e=>changePayment(o.id,e.target.value)}>{["unpaid","pending_verification","verified","rejected","refunded"].map(s=><option key={s} value={s}>{s.replace(/_/g," ")}</option>)}</select></td><td><select aria-label={"Order status for "+o.id} className={"order-status-select "+statusClass(o.status)} value={o.status.toLowerCase()} onChange={e=>changeStatus(o.id,e.target.value)}>{["Pending","Confirmed","Processing","Shipped","Delivered","Cancelled","Returned"].map(s=><option key={s} value={s.toLowerCase()}>{s}</option>)}</select></td></tr>)}</tbody></table>{rows.length===0&&<p className="admin-no-results">No matching orders found.</p>}</div>}
